 62	/**
 63	 * The MHPCO claim rules: what the office reimburses for a damage report against
 64	 * a policy, after the deductible and within the policy's payout cap.
 65	 *
 66	 * Two decisions the office revises on their own schedules meet here, in the
 67	 * order the specification fixes: its clause book states how much of a damage
 68	 * counts as reimbursable at all, and only then is the deductible borne. A new
 69	 * clause or a revised threshold is the clause book's business; repricing the
 70	 * deductible is this rule's.
 71	 *
 72	 * A payout is a payment out of the office, so its fraction of a G is rounded in
 73	 * the office's favor by {@link InOfficesFavor}.
 74	 */
 75	public class ClaimPolicy {
 76	
 77	    private static final BigDecimal DEDUCTIBLE_PER_DAMAGE = new BigDecimal("100");
 78	    private static final BigDecimal UNRULY_ITEM_REIMBURSEMENT_RATE = new BigDecimal("0.5");
 79	
 80	    /**
 81	     * The office reimburses the reimbursable part of a damage less the
 82	     * deductible, never below nothing.
 83	     */
 84	    public BigDecimal reimbursementFor(BigDecimal damageAmount, InsuredItem damagedItem) {
 85	        return InOfficesFavor.payment(reimbursableDamageUnderClauses(damageAmount, damagedItem)
 86	                .subtract(DEDUCTIBLE_PER_DAMAGE)
 87	                .max(BigDecimal.ZERO));
 88	    }
 89	
 90	    /**
 91	     * How much of a damage the office's clause book lets it count as
 92	     * reimbursable, read from the damaged item and settled before the
 93	     * deductible. The high-enchantment clause reimburses an unruly item's damage
 94	     * at a reduced rate; a damage no clause speaks to counts in full.
 95	     *
 96	     * The office's second clause, that damage to an item of dragon material is
 97	     * fully reimbursed, is absent here deliberately rather than by oversight: in
 98	     * every case the specification states it grants exactly what a damage no
 99	     * clause speaks to already earns. Below the unruly threshold it reimburses in
100	     * full, which is the default; at or above it the specification gives the
101	     * reduced rate precedence. So the clause never changes a reimbursement, and
102	     * the office does not record an item's material at all. A revision that gave
103	     * dragon material its own rate, or precedence over the high-enchantment
104	     * clause, would be the first to make the material worth recording.
105	     */
106	    private static BigDecimal reimbursableDamageUnderClauses(BigDecimal damageAmount,
107	            InsuredItem damagedItem) {
108	        if (damagedItem.isTooUnrulyToReimburseInFull()) {
109	            return damageAmount.multiply(UNRULY_ITEM_REIMBURSEMENT_RATE);
110	        }
111	        return damageAmount;
112	    }
113	}
114	import java.util.List;
