116	/**
117	 * What a policy covers: the items the office recorded when it wrote the policy,
118	 * able to say which of them a reported damage is settled on.
119	 *
120	 * Reading a damage report against the covered items is a decision of its own,
121	 * revised on its own schedule and quite apart from what one damage earns or what
122	 * the cap allows. Two pending revisions are this coverage's alone: counting a
123	 * policy's several items of one kind against the damages reported for that kind,
124	 * and refusing a damage that names a kind the policy does not cover. Neither
125	 * touches the claim rules or the cap.
126	 */
127	record Coverage(List<InsuredItem> insuredItems) {
128	
129	    static Coverage of(List<InsuredItem> insuredItems) {
130	        return new Coverage(List.copyOf(insuredItems));
131	    }
132	
133	    /**
134	     * The covered item whose terms a reported damage is settled on: the office
135	     * looks the reported kind of item up among the items it covers, and the
136	     * claim rules read the clauses from it. A damage naming a kind of item the
137	     * coverage does not include is no claim the office will settle.
138	     *
139	     * The office matches by the kind of item reported, which is all a single
140	     * covered item of a kind needs. Counting several items of one kind against
141	     * the damages reported for that kind is a separate decision the office has
142	     * not been asked to make yet.
143	     */
144	    InsuredItem itemDamagedBy(Damage damage) {
145	        for (InsuredItem insuredItem : insuredItems) {
146	            if (insuredItem.type().equals(damage.itemType())) {
147	                return insuredItem;
148	            }
149	        }
150	        throw new IllegalArgumentException(
151	                "the policy does not cover a " + damage.itemType());
152	    }
153	}
