156	/** One damage the customer reports: which kind of item was damaged, and by how much. */
157	public record Damage(String itemType, BigDecimal amount) {
158	}
159	/**
160	 * An item a policy covers, as the office records it.
161	 *
162	 * The office reads the recorded facts to classify the item's risk, so the
163	 * classifications live here with the facts they read, while what each risk
164	 * costs is the premium rules' business in {@link PremiumPolicy}. The
165	 * enchantment level carries more than one such classification: the premium
166	 * rules surcharge a high enchantment from level 5 up, and the claim rules have
167	 * their own, higher threshold, so each threshold is named for the rule it
168	 * serves rather than sharing one vague "enchanted" predicate.
169	 */
170	public record InsuredItem(String type, boolean cursed, int enchantment) {
171	
172	    private static final int HIGH_ENCHANTMENT_LEVEL = 5;
173	    private static final int UNRULY_ENCHANTMENT_LEVEL = 8;
174	
175	    /**
176	     * The office counts an item as highly enchanted, and so as carrying a risk
177	     * worth a surcharge, from enchantment level 5 up.
178	     */
179	    public boolean isHighlyEnchanted() {
180	        return enchantment >= HIGH_ENCHANTMENT_LEVEL;
181	    }
182	
183	    /**
184	     * From enchantment level 8 up the office considers an item too unruly for
185	     * its damage to be reimbursed in full. What such a damage earns instead is
186	     * the claim rules' clause to state, in {@link ClaimPolicy}.
187	     */
188	    public boolean isTooUnrulyToReimburseInFull() {
189	        return enchantment >= UNRULY_ENCHANTMENT_LEVEL;
190	    }
191	}
192	import java.math.BigDecimal;
