194	/**
195	 * The limit on everything a policy will ever pay out, and how much of it is
196	 * left. The office caps a policy at twice the insurance sum of the items it
197	 * covers.
198	 *
199	 * What the cap is worth and what it has left are one decision revised on its
200	 * own schedule: a revision to the multiple, or one that let the cap replenish,
201	 * is this cap's business and touches no claim rule. Premium modifiers are no
202	 * part of it, which is why a cap is opened from an insurance sum and never from
203	 * a premium.
204	 */
205	class PayoutCap {
206	
207	    private static final BigDecimal CAP_MULTIPLE_OF_INSURANCE_SUM = new BigDecimal("2");
208	
209	    private BigDecimal remaining;
210	
211	    static PayoutCap forInsuranceSum(BigDecimal insuranceSum) {
212	        return new PayoutCap(insuranceSum.multiply(CAP_MULTIPLE_OF_INSURANCE_SUM));
213	    }
214	
215	    private PayoutCap(BigDecimal remaining) {
216	        this.remaining = remaining;
217	    }
218	
219	    /** Pays what the cap still allows of a desired payout and consumes that much of it. */
220	    BigDecimal pay(BigDecimal desiredPayout) {
221	        BigDecimal paid = desiredPayout.min(remaining);
222	        remaining = remaining.subtract(paid);
223	        return paid;
224	    }
225	
226	    BigDecimal remaining() {
227	        return remaining;
228	    }
229	}
