233	/**
234	 * A policy the office has written: the {@link Coverage} it was written over and
235	 * the {@link PayoutCap} it was written under.
236	 *
237	 * Settling an incident against the policy is this policy's decision, not the
238	 * protocol's, and all it decides is how the three parties to a settlement meet:
239	 * the coverage says which covered item a reported damage is settled on, the
240	 * {@link ClaimPolicy} says what that one damage earns, and the cap says how much
241	 * of it is actually paid. So the deductible is borne once per damage reported
242	 * and the cap is consumed in the order the damages are reported.
243	 */
244	public class Policy {
245	
246	    private final Coverage coverage;
247	    private final PayoutCap payoutCap;
248	
249	    /**
250	     * The office writes a policy over the items a customer brings: what it
251	     * insures them for is the {@link PriceList}'s to state, and the cap that
252	     * insurance sum earns is the cap's own rule. Premium modifiers are no part
253	     * of it, which is why the policy is written from the covered items and never
254	     * from the premium quoted for them.
255	     */
256	    public static Policy covering(List<InsuredItem> insuredItems, PriceList priceList) {
257	        return new Policy(Coverage.of(insuredItems),
258	                PayoutCap.forInsuranceSum(priceList.insuranceSum(insuredItems)));
259	    }
260	
261	    private Policy(Coverage coverage, PayoutCap payoutCap) {
262	        this.coverage = coverage;
263	        this.payoutCap = payoutCap;
264	    }
265	
266	    /**
267	     * What the office pays for one reported incident: every damage reimbursed on
268	     * its own terms, the total limited to the cap the policy has left.
269	     */
270	    public BigDecimal settle(List<Damage> damages, ClaimPolicy claimPolicy) {
271	        BigDecimal paid = BigDecimal.ZERO;
272	        for (Damage damage : damages) {
273	            paid = paid.add(payoutCap.pay(claimPolicy.reimbursementFor(
274	                    damage.amount(), coverage.itemDamagedBy(damage))));
275	        }
276	        return paid;
277	    }
278	
279	    public BigDecimal remainingCap() {
280	        return payoutCap.remaining();
281	    }
282	}

