149	/**
150	 * The MHPCO premium rules: the two scopes of premium modifier, the processing
151	 * fee, applied to the base premium the {@link PriceList} states for the insured
152	 * items.
153	 *
154	 * A premium is a charge to the customer, so its fraction of a G is rounded in
155	 * the office's favor by {@link InOfficesFavor}.
156	 */
157	public class PremiumPolicy {
158	
159	    private static final BigDecimal CURSE_SURCHARGE_RATE = new BigDecimal("0.50");
160	    private static final BigDecimal HIGH_ENCHANTMENT_SURCHARGE_RATE = new BigDecimal("0.30");
161	    private static final BigDecimal FIRST_INSURANCE_SURCHARGE_RATE = new BigDecimal("0.10");
162	    private static final BigDecimal LOYALTY_DISCOUNT_RATE = new BigDecimal("0.20");
163	    private static final BigDecimal FOLLOW_UP_CONTRACT_DISCOUNT_RATE = new BigDecimal("0.15");
164	    private static final BigDecimal PROCESSING_FEE = new BigDecimal("5");
165	
166	    private final PriceList priceList;
167	
168	    /** The premium rules read their base premiums from the office's price list. */
169	    public PremiumPolicy(PriceList priceList) {
170	        this.priceList = priceList;
171	    }
172	
173	    /**
174	     * The office charges both kinds of modifier on a base premium, never on each
175	     * other: an item modifier on the affected item's own base premium, a
176	     * policy-wide modifier on the policy base premium. So the two are summed
177	     * alongside the base premium rather than compounded in sequence, and the
178	     * processing fee is added at the very end.
179	     */
180	    public int quote(Customer customer, List<InsuredItem> insuredItems) {
181	        BigDecimal policyBasePremium = priceList.policyBasePremium(insuredItems);
182	        BigDecimal premium = policyBasePremium
183	                .add(itemRiskSurcharges(insuredItems))
184	                .add(policyWideModifiers(policyBasePremium, customer))
185	                .add(PROCESSING_FEE);
186	        return InOfficesFavor.charge(premium).intValueExact();
187	    }
188	
189	    /**
190	     * Item-scope modifiers: each is charged on the base premium of the affected
191	     * item alone, so a modifier on one item never touches another item's share
192	     * of the policy. What one item's risks cost is {@link #riskSurcharge}'s
193	     * business; this rule only states that the policy owes the sum of them.
194	     */
195	    private BigDecimal itemRiskSurcharges(List<InsuredItem> insuredItems) {
196	        BigDecimal surcharges = BigDecimal.ZERO;
197	        for (InsuredItem insuredItem : insuredItems) {
198	            surcharges = surcharges.add(riskSurcharge(insuredItem));
199	        }
200	        return surcharges;
201	    }
202	
203	    /**
204	     * What the risks the office reads in one item cost, charged on that item's
205	     * own base premium. A curse and a high enchantment are separate risks, so an
206	     * item carrying both is surcharged for both rather than letting the graver
207	     * risk absorb the other.
208	     */
209	    private BigDecimal riskSurcharge(InsuredItem insuredItem) {
210	        BigDecimal itemBasePremium = priceList.basePremium(insuredItem);
211	        BigDecimal surcharge = BigDecimal.ZERO;
212	        if (insuredItem.cursed()) {
213	            surcharge = surcharge.add(itemBasePremium.multiply(CURSE_SURCHARGE_RATE));
214	        }
215	        if (insuredItem.isHighlyEnchanted()) {
216	            surcharge = surcharge.add(itemBasePremium.multiply(HIGH_ENCHANTMENT_SURCHARGE_RATE));
217	        }
218	        return surcharge;
219	    }
220	
221	    /**
222	     * Policy-scope modifiers: each is charged on the policy base premium, the
223	     * sum of all item base premiums. Every quote is a first insurance of the
224	     * items it covers, whatever the customer's history.
225	     */
226	    private BigDecimal policyWideModifiers(BigDecimal policyBasePremium, Customer customer) {
227	        return firstInsuranceSurcharge(policyBasePremium)
228	                .subtract(loyaltyDiscount(policyBasePremium, customer))
229	                .subtract(followUpContractDiscount(policyBasePremium, customer));
230	    }
231	
232	    /**
233	     * Every contract after the customer's first earns a discount, however long
234	     * they have been with the office.
235	     */
236	    private static BigDecimal followUpContractDiscount(BigDecimal policyBasePremium,
237	            Customer customer) {
238	        if (!customer.holdsFollowUpContract()) {
239	            return BigDecimal.ZERO;
240	        }
241	        return policyBasePremium.multiply(FOLLOW_UP_CONTRACT_DISCOUNT_RATE);
242	    }
243	
244	    /**
245	     * Every quote is a first insurance of the items it covers, whatever the
246	     * customer's history, so this surcharge is charged on every policy.
247	     */
248	    private static BigDecimal firstInsuranceSurcharge(BigDecimal policyBasePremium) {
249	        return policyBasePremium.multiply(FIRST_INSURANCE_SURCHARGE_RATE);
250	    }
251	
252	    /**
253	     * The office rewards a long-standing customer with a discount on the policy
254	     * base premium. Who counts as long-standing is the customer's standing to
255	     * answer; this rule only states what that standing is worth.
256	     */
257	    private static BigDecimal loyaltyDiscount(BigDecimal policyBasePremium, Customer customer) {
258	        if (!customer.isLongStanding()) {
259	            return BigDecimal.ZERO;
260	        }
261	        return policyBasePremium.multiply(LOYALTY_DISCOUNT_RATE);
262	    }
263	}
264	import java.math.BigDecimal;
265	import java.math.RoundingMode;
266	
267	/**
268	 * The MHPCO rounds every amount to whole G in its own favor. One rule, read in
269	 * the direction the money moves: a fraction of a G the customer owes the office
270	 * is rounded up, a fraction the office owes the customer is rounded down. The
271	 * office never loses the fraction.
272	 *
273	 * Intermediate amounts during a calculation stay exact fractions; only a final
274	 * charge or payment is rounded.
275	 */
276	final class InOfficesFavor {
277	
278	    private static final int WHOLE_G = 0;
279	
280	    private InOfficesFavor() {
281	    }
282	
283	    /** What the customer owes the office, rounded up: the fraction favors the office. */
284	    static BigDecimal charge(BigDecimal amount) {
285	        return amount.setScale(WHOLE_G, RoundingMode.CEILING);
286	    }
287	
288	    /** What the office owes the customer, rounded down: the fraction favors the office. */
289	    static BigDecimal payment(BigDecimal amount) {
290	        return amount.setScale(WHOLE_G, RoundingMode.FLOOR);
291	    }
