341	public class ClaimOfficeCli {
342	
343	    private static final ObjectMapper JSON = new ObjectMapper();
344	
345	    public void run(InputStream scenario, PrintStream results) {
346	        try {
347	            JsonNode input = JSON.readTree(scenario);
348	            ClaimOffice office =
349	                    new ClaimOffice(input.get("customer").get("yearsWithMHPCO").asInt());
350	            ObjectNode output = JSON.createObjectNode();
351	            ArrayNode resultsNode = output.putArray("results");
352	            JsonNode steps = input.get("steps");
353	            for (int stepIndex = 0; stepIndex < steps.size(); stepIndex++) {
354	                JsonNode step = steps.get(stepIndex);
355	                if ("claim".equals(step.get("op").asText())) {
356	                    writeSettlement(office.settleClaim(step.get("policy").asInt(), damages(step)),
357	                            resultsNode.addObject());
358	                    continue;
359	                }
360	                resultsNode.addObject().put("premium",
361	                        office.quote(stepIndex, insuredItems(step)));
362	            }
363	            results.print(JSON.writeValueAsString(output));
364	        } catch (IOException e) {
365	            throw new UncheckedIOException(e);
366	        }
367	    }
368	
369	    private static void writeSettlement(ClaimOffice.Settlement settlement, ObjectNode result) {
370	        result.put("payout", settlement.payout().intValueExact());
371	        result.put("remainingCap", settlement.remainingCap().intValueExact());
372	    }
373	
374	    private static List<Damage> damages(JsonNode claimStep) {
375	        List<Damage> damages = new ArrayList<>();
376	        for (JsonNode damage : claimStep.get("incident").get("damages")) {
377	            damages.add(new Damage(damage.get("itemType").asText(),
378	                    new BigDecimal(damage.get("amount").asText())));
379	        }
380	        return damages;
381	    }
382	
383	    private static List<InsuredItem> insuredItems(JsonNode quoteStep) {
384	        List<InsuredItem> items = new ArrayList<>();
385	        for (JsonNode item : quoteStep.get("items")) {
386	            items.add(new InsuredItem(item.get("type").asText(),
387	                    item.path("cursed").asBoolean(false),
388	                    item.path("enchantment").asInt(0)));
389	        }
390	        return items;
